set-variable.value:
@{
      var json = System.Text.Encoding.UTF8.GetString(
        System.Convert.FromBase64String("{{teams-agent-bot-ids}}"));
      var map = Newtonsoft.Json.Linq.JObject.Parse(json);
      var agentName = (string)context.Variables["agent-name"];
      return map[agentName]?.ToString() ?? string.Empty;
    }

@{
      var json = System.Text.Encoding.UTF8.GetString(
        System.Convert.FromBase64String("{{teams-agent-versions}}"));
      var map = Newtonsoft.Json.Linq.JObject.Parse(json);
      var agentName = (string)context.Variables["agent-name"];
      return map[agentName]?.ToString() ?? string.Empty;
    }

return-response.set-body:
@{
            return new Newtonsoft.Json.Linq.JObject(
              new Newtonsoft.Json.Linq.JProperty("error", "Unknown hosted agent route."),
              new Newtonsoft.Json.Linq.JProperty("agent", (string)context.Variables["agent-name"])
            ).ToString();
          }

@{
                var response = context.Variables.GetValueOrDefault<IResponse>("session-response", null);
                return new Newtonsoft.Json.Linq.JObject(
                  new Newtonsoft.Json.Linq.JProperty("error", "Foundry session creation failed."),
                  new Newtonsoft.Json.Linq.JProperty("agent", (string)context.Variables["agent-name"]),
                  new Newtonsoft.Json.Linq.JProperty("version", (string)context.Variables["agent-version"]),
                  new Newtonsoft.Json.Linq.JProperty("foundryStatus", response?.StatusCode),
                  new Newtonsoft.Json.Linq.JProperty(
                    "details",
                    response?.Body?.As<string>(preserveContent: true) ?? "No response from Foundry.")
                ).ToString(Newtonsoft.Json.Formatting.None);
              }

set-variable.value:
@{
          var response = (IResponse)context.Variables["session-response"];
          var body = response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
          return body["agent_session_id"]?.ToString() ?? string.Empty;
        }

return-response.set-body:
@{
                return new Newtonsoft.Json.Linq.JObject(
                  new Newtonsoft.Json.Linq.JProperty("error", "Foundry did not return agent_session_id."),
                  new Newtonsoft.Json.Linq.JProperty("agent", (string)context.Variables["agent-name"]),
                  new Newtonsoft.Json.Linq.JProperty("version", (string)context.Variables["agent-version"])
                ).ToString(Newtonsoft.Json.Formatting.None);
              }
